import React, { useEffect, useState } from "react";
import axios from "axios";
import * as XLSX from "xlsx"; 
import jsPDF from "jspdf";
import "jspdf-autotable";
import config from "../config";

export default function AdminDashboard() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    axios
      .get(`${config.apiUrl}/admin/orders`)
      .then((res) => setOrders(res.data))
      .catch((err) => console.log("Error fetching orders:", err));
  }, []);

  const exportExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(orders);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Orders");
    XLSX.writeFile(workbook, "Orders.xlsx");
  };

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.text("Orders Report", 14, 10);
    doc.autoTable({
      head: [["Order ID", "Customer", "Amount", "Status", "Date"]],
      body: orders.map((order) => [
        order.id,
        order.customer_name,
        `₹ ${order.total_amount}`,
        order.status,
        new Date(order.created_at).toLocaleDateString(),
      ]),
      startY: 20,
    });
    doc.save("Orders.pdf");
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Admin Dashboard</h2>

      <div style={styles.exportButtons}>
        <button style={styles.btnExcel} onClick={exportExcel}>
          Export Excel
        </button>
        <button style={styles.btnPdf} onClick={exportPDF}>
          Export PDF
        </button>
      </div>

      <table style={styles.table}>
        <thead>
          <tr>
            <th style={styles.th}>Order ID</th>
            <th style={styles.th}>Customer</th>
            <th style={styles.th}>Amount</th>
            <th style={styles.th}>Status</th>
            <th style={styles.th}>Date</th>
          </tr>
        </thead>
        <tbody>
          {orders.length > 0 ? (
            orders.map((order) => (
              <tr key={order.id}>
                <td style={styles.td}>{order.id}</td>
                <td style={styles.td}>{order.customer_name}</td>
                <td style={styles.td}>₹ {order.total_amount}</td>
                <td style={styles.td}>{order.status}</td>
                <td style={styles.td}>
                  {new Date(order.created_at).toLocaleDateString()}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td style={styles.emptyRow} colSpan="5">
                No orders found
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

const styles = {
  container: { width: "90%", margin: "30px auto", textAlign: "center" },
  heading: { fontSize: "28px", marginBottom: "20px" },
  exportButtons: { marginBottom: "15px" },
  btnExcel: {
    padding: "8px 15px",
    background: "#1f8f02",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    marginRight: "10px",
    cursor: "pointer"
  },
  btnPdf: {
    padding: "8px 15px",
    background: "#c51a1a",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer"
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
    background: "#fff",
    borderRadius: "8px",
    overflow: "hidden"
  },
  th: {
    background: "#007bff",
    color: "#fff",
    padding: "10px"
  },
  td: {
    padding: "10px",
    borderBottom: "1px solid #ccc"
  },
  emptyRow: {
    padding: "15px",
    fontStyle: "italic",
    textAlign: "center"
  }
};
